ALTER TABLE "payroll_monthly_entry" ADD CONSTRAINT "payroll_monthly_entry_salary_snapshot" CHECK (("payroll_monthly_entry"."salary" is not null and "payroll_monthly_entry"."source_token" is not null) or ("payroll_monthly_entry"."salary" is null and "payroll_monthly_entry"."source_token" is null and "payroll_monthly_entry"."status" <> 'finalized' and "payroll_monthly_entry"."base_minor" = 0 and "payroll_monthly_entry"."worked_seconds" = 0 and not "payroll_monthly_entry"."manual_base" and "payroll_monthly_entry"."base_reason" = '' and "payroll_monthly_entry"."fine_minor" = 0));--> statement-breakpoint
ALTER TABLE "payroll_monthly_entry" ADD CONSTRAINT "payroll_monthly_entry_evidence" CHECK (length(trim("payroll_monthly_entry"."reason")) between 5 and 500 and length("payroll_monthly_entry"."base_reason") <= 500 and (not "payroll_monthly_entry"."manual_base" or length(trim("payroll_monthly_entry"."base_reason")) >= 5) and jsonb_typeof("payroll_monthly_entry"."adjustments") = 'array' and jsonb_array_length("payroll_monthly_entry"."adjustments") <= 20 and ("payroll_monthly_entry"."source_token" is null or "payroll_monthly_entry"."source_token" ~ '^[a-f0-9]{64}$') and "payroll_monthly_entry"."command_hash" ~ '^[a-f0-9]{64}$');